arguments.command:
cat > /tmp/mk.sh <<'EOF'
#!/bin/bash
# usage: mk.sh <dir>  (reads txtar from stdin: "-- path --" headers)
dir=$1; rm -rf "$dir"; mkdir -p "$dir"
awk -v d="$dir" '
/^-- .* --$/ { f=substr($0,4,length($0)-6); fn=d "/" f; sub(/\/[^\/]*$/,"",fn); system("mkdir -p \"" fn "\""); out=d "/" f; printf "" > out; next }
{ if (out!="") print >> out }
' 
if [ ! -f "$dir/go.mod" ]; then printf 'module example.com/m\n\ngo 1.27\n' > "$dir/go.mod"; fi
EOF
chmod +x /tmp/mk.sh
/tmp/mk.sh /tmp/t3 <<'EOF'
-- a/user.go --
package a

type user struct {
	//declscope:private
	name string
}

//declscope:shared
func Helper() {}

//declscope:ignore boundary
func greet(u user) string { return u.name }
EOF
cd /tmp/t3 && cat a/user.go && /tmp/run.sh /workspace/executable ./...

