import hashlib, os, sys, re
JUNK = {'.DS_Store', 'Thumbs.db', 'desktop.ini'}
META = ('x-embedded-by', 'x-embedded-version', 'x-embedded-at', 'x-embedded-digest')
def normalize(data):
    lines = data.split(b'\n')
    if not lines or lines[0] != b'---':
        return data
    out = [lines[0]]
    i = 1
    while i < len(lines):
        l = lines[i]
        if l == b'---':
            out.extend(lines[i:]); break
        key = l.split(b':', 1)[0]
        if key.decode('utf-8', 'replace') in META:
            i += 1; continue
        out.append(l); i += 1
    return b'\n'.join(out)
def digest(root):
    h = hashlib.sha256()
    recs = []
    for dp, dns, fns in os.walk(root):
        dns.sort()
        for fn in fns:
            if fn in JUNK: continue
            full = os.path.join(dp, fn)
            rel = os.path.relpath(full, root)
            recs.append(rel)
    recs.sort()
    for rel in recs:
        data = open(os.path.join(root, rel), 'rb').read()
        if rel == 'SKILL.md': data = normalize(data)
        h.update(rel.encode() + b'\x00' + str(len(data)).encode() + b'\x00' + data)
    return 'sha256:' + h.hexdigest()
if __name__ == '__main__':
    print(digest(sys.argv[1]))
EOF
