#!/bin/bash
# usage: mkstate.sh <state> <skilldir>  -- turns an up-to-date installed skill dir into the given state
s=$1; D=$2; F=$D/SKILL.md
case $s in
  missing) rm -rf "$D";;
  uptodate) ;;
  modified) echo x >> "$F";;
  outdated) echo x >> "$F"; /tmp/skr/setdig2.sh "$D";;
  foreign) sed -i '/^x-embedded-by: /d' "$F";;
  foreign-other) sed -i 's/^x-embedded-by: .*/x-embedded-by: other/' "$F";;
  foreign-nofm) printf 'hello\n' > "$F";;
  foreign-nofile) rm -f "$F";;
  foreign-file) rm -rf "$D"; echo hi > "$D";;
  foreign-symlinkfile) ln -s /etc/hostname "$D/link";;
  dangling) rm -rf "$D"; ln -s /nonexistent "$D";;
  emptydir) rm -rf "$D"; mkdir "$D";;
  unreadable) chmod 000 "$D";;
esac
EOF
