// inw watches directories (recursively at start, and newly created dirs) with inotify and prints events.
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

func main() {
	fd, err := syscall.InotifyInit1(syscall.IN_CLOEXEC)
	if err != nil {
		panic(err)
	}
	wds := map[int]string{}
	add := func(p string) {
		wd, err := syscall.InotifyAddWatch(fd, p, syscall.IN_ALL_EVENTS&^(syscall.IN_ACCESS|syscall.IN_CLOSE_NOWRITE|syscall.IN_OPEN))
		if err == nil {
			wds[wd] = p
		}
	}
	for _, root := range os.Args[1:] {
		filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
			if err == nil && info.IsDir() {
				add(p)
			}
			return nil
		})
	}
	fmt.Println("READY")
	os.Stdout.Sync()
	buf := make([]byte, 65536)
	deadline := time.Now().Add(5 * time.Second)
	go func() { time.Sleep(time.Until(deadline)); os.Exit(0) }()
	for {
		n, err := syscall.Read(fd, buf)
		if err != nil {
			return
		}
		for off := 0; off < n; {
			ev := (*syscall.InotifyEvent)(unsafe.Pointer(&buf[off]))
			name := ""
			if ev.Len > 0 {
				b := buf[off+syscall.SizeofInotifyEvent : off+syscall.SizeofInotifyEvent+int(ev.Len)]
				name = strings.TrimRight(string(b), "\x00")
			}
			dir := wds[int(ev.Wd)]
			var names []string
			m := ev.Mask
			for _, f := range []struct {
				b uint32
				s string
			}{{syscall.IN_CREATE, "CREATE"}, {syscall.IN_DELETE, "DELETE"}, {syscall.IN_MODIFY, "MODIFY"}, {syscall.IN_MOVED_FROM, "MOVED_FROM"}, {syscall.IN_MOVED_TO, "MOVED_TO"}, {syscall.IN_ATTRIB, "ATTRIB"}, {syscall.IN_CLOSE_WRITE, "CLOSE_WRITE"}, {syscall.IN_DELETE_SELF, "DELETE_SELF"}, {syscall.IN_MOVE_SELF, "MOVE_SELF"}, {syscall.IN_ISDIR, "ISDIR"}} {
				if m&f.b != 0 {
					names = append(names, f.s)
				}
			}
			if m&syscall.IN_CREATE != 0 && m&syscall.IN_ISDIR != 0 {
				add(filepath.Join(dir, name))
			}
			fmt.Printf("%s %s %s\n", strings.Join(names, "|"), dir, name)
			off += syscall.SizeofInotifyEvent + int(ev.Len)
		}
	}
}
EOF
