package load

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/scanner"
	"go/token"
	"go/types"
	"io"
	"os"
	"runtime"
	"sort"
	"sync"
)

// Package is a loaded package.
type Package struct {
	ID              string
	Name            string
	PkgPath         string
	Dir             string
	Errors          []Error
	TypeErrors      []types.Error
	GoFiles         []string
	CompiledGoFiles []string
	OtherFiles      []string
	EmbedFiles      []string
	IgnoredFiles    []string
	ExportFile      string
	Imports         map[string]*Package
	Types           *types.Package
	Fset            *token.FileSet
	IllTyped        bool
	Syntax          []*ast.File
	TypesInfo       *types.Info
	TypesSizes      types.Sizes
	Module          *Module
	ForTest         string
	DepOnly         bool
	Initial         bool

	// Raw is the go list record.
	Raw *jsonPackage

	needsrc, needtypes bool
	importErrors       map[string]error
	color              int
	loaded             bool
}

// CgoFiles returns the package's cgo files as absolute paths.
func (p *Package) CgoFiles() []string {
	if p.Raw == nil {
		return nil
	}
	return absJoin(p.Dir, p.Raw.CgoFiles)
}

// IgnoredGoFiles returns the build-excluded Go files as absolute paths.
func (p *Package) IgnoredGoFiles() []string {
	if p.Raw == nil {
		return nil
	}
	return absJoin(p.Dir, p.Raw.IgnoredGoFiles)
}

// RawGoFiles returns the Go files as listed (without cgo files), absolute.
func (p *Package) RawGoFiles() []string {
	if p.Raw == nil {
		return nil
	}
	return absJoin(p.Dir, p.Raw.GoFiles)
}

// TestGoFiles returns the in-package test files, absolute.
func (p *Package) TestGoFiles() []string {
	if p.Raw == nil {
		return nil
	}
	return absJoin(p.Dir, p.Raw.TestGoFiles)
}

// XTestGoFiles returns the external test files, absolute.
func (p *Package) XTestGoFiles() []string {
	if p.Raw == nil {
		return nil
	}
	return absJoin(p.Dir, p.Raw.XTestGoFiles)
}

func (p *Package) String() string { return p.ID }

type parseValue struct {
	f     *ast.File
	err   error
	ready chan struct{}
}

type loader struct {
	cfg      *Config
	fset     *token.FileSet
	pkgs     map[string]*Package
	sizes    types.Sizes
	imp      types.ImporterFrom
	byPath   map[string]*Package // export-data packages by path
	parseMu  sync.Mutex
	cache    map[string]*parseValue
	exportMu sync.Mutex
}

// Load loads the packages named by patterns.
func Load(cfg *Config, patterns ...string) ([]*Package, error) {
	state := &golistState{cfg: cfg}
	response, err := state.driver(patterns)
	if err != nil {
		return nil, err
	}
	ld := &loader{
		cfg:   cfg,
		fset:  token.NewFileSet(),
		cache: make(map[string]*parseValue),
	}
	if !cfg.NoTypes {
		ld.sizes = types.SizesFor(response.Compiler, response.Arch)
		if ld.sizes == nil {
			return nil, fmt.Errorf("can't determine type sizes for compiler %q on GOARCH %q", response.Compiler, response.Arch)
		}
	}
	return ld.refine(response)
}

func (ld *loader) refine(response *driverResponse) ([]*Package, error) {
	roots := response.Roots
	rootMap := make(map[string]int, len(roots))
	for i, root := range roots {
		rootMap[root] = i
	}
	ld.pkgs = make(map[string]*Package)
	initial := make([]*Package, len(roots))
	types := !ld.cfg.NoTypes
	for _, pkg := range response.Packages {
		rootIndex := -1
		if i, found := rootMap[pkg.ID]; found {
			rootIndex = i
		}
		exportDataInvalid := pkg.ExportFile == "" && pkg.PkgPath != "unsafe"
		pkg.needtypes = types && (rootIndex >= 0 || ld.cfg.Deps)
		pkg.needsrc = (types && (rootIndex >= 0 || ld.cfg.Deps) || types && exportDataInvalid) && pkg.PkgPath != "unsafe"
		pkg.Fset = ld.fset
		ld.pkgs[pkg.ID] = pkg
		if rootIndex >= 0 {
			initial[rootIndex] = pkg
			pkg.Initial = true
		}
	}
	for i, root := range roots {
		if initial[i] == nil {
			return nil, fmt.Errorf("root package %v is missing", root)
		}
	}

	const (
		white = 0
		grey  = 1
		black = 2
	)
	var stack []*Package
	var visit func(lpkg *Package) bool
	visit = func(lpkg *Package) bool {
		if lpkg.color == grey {
			panic("internal error: grey node")
		}
		if lpkg.color == white {
			lpkg.color = grey
			stack = append(stack, lpkg)
			stubs := lpkg.Imports
			lpkg.Imports = make(map[string]*Package, len(stubs))
			paths := make([]string, 0, len(stubs))
			for p := range stubs {
				paths = append(paths, p)
			}
			sort.Strings(paths)
			for _, importPath := range paths {
				ipkg := stubs[importPath]
				var importErr error
				imp := ld.pkgs[ipkg.ID]
				if imp == nil {
					importErr = fmt.Errorf("missing package: %q", ipkg.ID)
				} else if imp.color == grey {
					importErr = fmt.Errorf("import cycle: %s", stack)
				}
				if importErr != nil {
					if lpkg.importErrors == nil {
						lpkg.importErrors = make(map[string]error)
					}
					lpkg.importErrors[importPath] = importErr
					continue
				}
				if visit(imp) {
					lpkg.needsrc = true
				}
				lpkg.Imports[importPath] = imp
			}
			if lpkg.needsrc && types {
				for _, ipkg := range lpkg.Imports {
					ipkg.needtypes = true
				}
			}
			if types {
				lpkg.TypesSizes = ld.sizes
			}
			stack = stack[:len(stack)-1]
			lpkg.color = black
		}
		return lpkg.needsrc
	}
	for _, lpkg := range initial {
		visit(lpkg)
	}

	if types {
		ld.byPath = make(map[string]*Package)
		for _, p := range ld.pkgs {
			if !p.needsrc && p.ExportFile != "" {
				ld.byPath[p.PkgPath] = p
			}
		}
		ld.imp = importer.ForCompiler(ld.fset, "gc", func(path string) (io.ReadCloser, error) {
			p := ld.byPath[path]
			if p == nil || p.ExportFile == "" {
				return nil, fmt.Errorf("no export data for %q", path)
			}
			return os.Open(p.ExportFile)
		}).(types.ImporterFrom)
		ld.loadAll(initial)
	}
	return initial, nil
}

// loadAll loads every package reachable from the initial ones, dependencies
// first. Source packages are type-checked in parallel once their imports are
// done.
func (ld *loader) loadAll(initial []*Package) {
	var order []*Package
	seen := make(map[*Package]bool)
	var post func(p *Package)
	post = func(p *Package) {
		if seen[p] {
			return
		}
		seen[p] = true
		paths := make([]string, 0, len(p.Imports))
		for path := range p.Imports {
			paths = append(paths, path)
		}
		sort.Strings(paths)
		for _, path := range paths {
			post(p.Imports[path])
		}
		order = append(order, p)
	}
	for _, p := range initial {
		post(p)
	}
	// Pre-parse every source file concurrently.
	var files []string
	for _, p := range order {
		if p.needsrc && p.PkgPath != "unsafe" {
			files = append(files, p.CompiledGoFiles...)
		}
	}
	var wg sync.WaitGroup
	sem := make(chan struct{}, runtime.GOMAXPROCS(0)+4)
	for _, f := range files {
		wg.Add(1)
		sem <- struct{}{}
		go func(f string) {
			defer wg.Done()
			ld.parseFile(f)
			<-sem
		}(f)
	}
	wg.Wait()

	// Type-check in dependency order, running independent packages in parallel.
	done := make(map[*Package]chan struct{}, len(order))
	for _, p := range order {
		done[p] = make(chan struct{})
	}
	for _, p := range order {
		wg.Add(1)
		go func(p *Package) {
			defer wg.Done()
			for _, imp := range p.Imports {
				<-done[imp]
			}
			ld.loadPackage(p)
			close(done[p])
		}(p)
	}
	wg.Wait()
}

func (ld *loader) parseFile(filename string) (*ast.File, error) {
	ld.parseMu.Lock()
	v, ok := ld.cache[filename]
	if ok {
		ld.parseMu.Unlock()
		<-v.ready
		return v.f, v.err
	}
	v = &parseValue{ready: make(chan struct{})}
	ld.cache[filename] = v
	ld.parseMu.Unlock()
	src, err := os.ReadFile(filename)
	if err != nil {
		v.err = err
	} else {
		v.f, v.err = parser.ParseFile(ld.fset, filename, src, parser.AllErrors|parser.ParseComments)
	}
	close(v.ready)
	return v.f, v.err
}

func (ld *loader) parseFiles(filenames []string) ([]*ast.File, []error) {
	var parsed []*ast.File
	var errs []error
	for _, filename := range filenames {
		f, err := ld.parseFile(filename)
		if f != nil {
			parsed = append(parsed, f)
		}
		if err != nil {
			errs = append(errs, err)
		}
	}
	return parsed, errs
}

