	var out []*finding
	all := m.scopeDirectives()
	for _, dir := range all {
		reach := m.reached(dir)
		prefix := "unused //declscope:" + dir.name
		if dir.fileLevel {
			prefix = "unused file-level //declscope:" + dir.name
		}
		if len(reach) == 0 {
			msg := prefix
			if !dir.fileLevel {
				msg += ": no checked declaration carries it"
			}
			out = append(out, &finding{rule: "unused", pos: dir.pos(), message: msg, dir: dir, unusedOf: true})
			continue
		}
		skip := map[*directive]bool{dir: true}
		same, configFree := true, true
		for _, d := range reach {
			s, src := m.scopeOf(d, skip)
			if s != dir.name {
				same = false
			}
			if src.kind == srcDefault {
