	for _, u := range cross {
		f.related = append(f.related, checker.RelatedInformation{
			Pos:     u.ident.Pos(),
			End:     u.ident.End(),
			Message: "used here, in " + u.file.ns.describe(),
		})
	}
	if fixes && d.source.kind == srcDefault {
		if d.member && d.typeDecl != nil && m.typeGetsFix(d.typeDecl) {
			return f
		}
		f.fix = m.shareFix(d)
	}
	return f
