	for _, ft := range d.target.children {
		if ft.kind != tField || len(ft.anchors) == 0 || ft.scope != nil {
			continue
		}
		narrow := true
		for _, a := range ft.anchors {
			if a.exported || a.source.kind != srcDefault || len(a.crossing()) > 0 {
				narrow = false
				break
			}
		}
		if !narrow {
			continue
		}
