			out = append(out, f)
		}
	}
	return out
}

// scopeDirectives lists every effective scope directive.
func (m *model) scopeDirectives() []*directive {
	var out []*directive
	for _, f := range m.files {
		for _, d := range f.directives {
			if d.effective && d.isScope() {
				out = append(out, d)
			}
		}
	}
	return out
}

// redundant reports whether deleting dir would change no scope, with the
// directives in skip already deleted.
func (m *model) redundant(dir *directive, skip map[*directive]bool) bool {
	reach := m.reachedSkipping(dir, skip)
	if len(reach) == 0 {
		return false
	}
	s2 := map[*directive]bool{dir: true}
	for k := range skip {
		s2[k] = true
	}
	for _, d := range reach {
		if s, _ := m.scopeOf(d, s2); s != dir.name {
			return false
		}
	}
	return true
}

func (m *model) reachedSkipping(dir *directive, skip map[*directive]bool) []*decl {
	var out []*decl
	for _, d := range m.decls {
		if _, src := m.scopeOf(d, skip); src.dir == dir {
			out = append(out, d)
		}
	}
	return out
}

// unusedScopeFindings reports scope directives that change nothing.
func (m *model) unusedScopeFindings(fixes bool, base []*finding) []*finding {
	if m.rules.Unused == "off" {
		return nil
	}
	var out []*finding
	all := m.scopeDirectives()
	for _, dir := range all {
		reach := m.reached(dir)
		prefix := "unused //declscope:" + dir.name
		if dir.fileLevel {
			prefix = "unused file-level //declscope:" + dir.name
		}
		if len(reach) == 0 {
			msg := prefix
			if !dir.fileLevel {
				msg += ": no checked declaration carries it"
			}
			out = append(out, &finding{rule: "unused", pos: dir.pos(), message: msg, dir: dir, unusedOf: true})
			continue
		}
		skip := map[*directive]bool{dir: true}
		same, configFree := true, true
		for _, d := range reach {
			s, src := m.scopeOf(d, skip)
			if s != dir.name {
				same = false
			}
			if src.kind == srcDefault {
				configFree = false
			}
		}
		if !same {
			continue
		}
		names := m.dirNames(dir, reach)
		if m.rules.Unused == "loose" {
			if !configFree {
				continue
			}
			msg := prefix
			if !dir.fileLevel {
				msg = fmt.Sprintf("%s on %s: nothing it reaches takes a scope", prefix, strings.Join(names, ", "))
			}
			out = append(out, &finding{rule: "unused", pos: dir.pos(), message: msg, dir: dir, unusedOf: true})
			continue
		}
		// Deleting it must not make a nearer directive redundant.
		keeps := false
		for _, other := range all {
			if other == dir {
				continue
			}
			if !m.redundant(other, nil) && m.redundant(other, skip) {
				keeps = true
				break
			}
		}
		if keeps {
			continue
		}
		var msg string
		if dir.fileLevel {
			msg = fmt.Sprintf("%s: every declaration it reaches already has %s scope", prefix, dir.name)
		} else {
			each := "it already has"
			if len(names) > 1 {
				each = "each already has"
			}
			msg = fmt.Sprintf("%s on %s: %s %s scope", prefix, strings.Join(names, ", "), each, dir.name)
		}
		f := &finding{rule: "unused", pos: dir.pos(), message: msg, dir: dir, unusedOf: true}
		if fixes && !(m.unseenTests && !m.testVariant) && !m.changesFindings(dir, base) {
			f.fix = &checker.SuggestedFix{
				Message:   "remove //declscope:" + dir.name,
				TextEdits: []checker.TextEdit{m.deleteDirective(dir)},
			}
		}
		out = append(out, f)
	}
	return out
}

// dirNames lists what a directive is written on, for messages.
func (m *model) dirNames(dir *directive, reach []*decl) []string {
	var names []string
	for _, d := range reach {
		if dir.target != nil && dir.target.kind != tField && d.member {
			continue
		}
		names = append(names, d.display)
	}
	return names
}

// changesFindings reports whether deleting dir would change any finding
// other than the unused ones.
func (m *model) changesFindings(dir *directive, base []*finding) bool {
	m.resolveScopes(map[*directive]bool{dir: true})
	defer m.resolveScopes(nil)
	after := m.declFindings(true)
	if len(after) != len(base) {
		return true
	}
	for i := range after {
		a, b := after[i], base[i]
		if a.rule != b.rule || a.pos != b.pos || a.message != b.message {
			return true
		}
	}
	return false
}

// deleteDirective removes the line of a directive.
func (m *model) deleteDirective(dir *directive) checker.TextEdit {
	c := dir.comment
	tf := m.fset.File(c.Pos())
	src := m.source(tf.Name())
	start := tf.Offset(c.Pos())
	end := tf.Offset(c.End())
	lineStart := start
	for lineStart > 0 && src[lineStart-1] != '\n' && (src[lineStart-1] == ' ' || src[lineStart-1] == '\t') {
		lineStart--
	}
	if lineStart == 0 || src[lineStart-1] == '\n' {
		// The directive is alone on its line: delete the whole line.
		if end < len(src) && src[end] == '\n' {
			end++
		}
		if dir.fileLevel && end < len(src) && src[end] == '\n' && (lineStart == 0 || src[lineStart-1] == '\n') {
			// Above the package clause a deleted group leaves no blank line.
			if lineStart < 2 || src[lineStart-2] == '\n' || lineStart == 0 {
				end++
			}
		}
		return checker.TextEdit{Pos: tf.Pos(lineStart), End: tf.Pos(end), NewText: nil}
	}
	// A trailing directive: delete it with the space before it.
	return checker.TextEdit{Pos: tf.Pos(lineStart), End: tf.Pos(end), NewText: nil}
}

// sortByPos orders findings by file name, then offset.
func (m *model) sortByPos(fs []*finding) {
	sort.SliceStable(fs, func(i, j int) bool {
		pi, pj := m.fset.Position(fs[i].pos), m.fset.Position(fs[j].pos)
		if pi.Filename != pj.Filename {
			return pi.Filename < pj.Filename
		}
		return pi.Offset < pj.Offset
	})
}

