// Command runbin runs the reference binary on every case of the given corpus
// files and caches its output in /tmp/ycmp/cache.json.
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
)

const cacheFile = "/tmp/ycmp/cache.json"

func readCorpus(files []string) []string {
	var cases []string
	for _, f := range files {
		fh, err := os.Open(f)
		if err != nil {
			panic(err)
		}
		sc := bufio.NewScanner(fh)
		sc.Buffer(make([]byte, 1<<20), 1<<24)
		ln := 0
		for sc.Scan() {
			ln++
			line := strings.TrimSpace(sc.Text())
			if line == "" || strings.HasPrefix(line, "//") {
				continue
			}
			s, err := strconv.Unquote(line)
			if err != nil {
				panic(fmt.Sprintf("%s:%d: %v", f, ln, err))
			}
			cases = append(cases, s)
		}
		fh.Close()
	}
	return cases
}

func main() {
	cache := map[string]string{}
	if b, err := os.ReadFile(cacheFile); err == nil {
		json.Unmarshal(b, &cache)
	}
	var todo []string
	seen := map[string]bool{}
	for _, c := range readCorpus(os.Args[1:]) {
		if _, ok := cache[c]; !ok && !seen[c] {
			seen[c] = true
			todo = append(todo, c)
		}
	}
	const workers = 8
	var mu sync.Mutex
	var wg sync.WaitGroup
	ch := make(chan string)
	for w := 0; w < workers; w++ {
		dir := fmt.Sprintf("/tmp/yt_w%d", w)
		os.MkdirAll(filepath.Join(dir, "p"), 0o755)
		os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module example.com/m\n\ngo 1.27\n"), 0o644)
		os.WriteFile(filepath.Join(dir, "p", "a.go"), []byte("package p\n\nfunc f() {}\n"), 0o644)
		wg.Add(1)
		go func() {
			defer wg.Done()
			cfg := filepath.Join(dir, ".declscope.yaml")
			for c := range ch {
				os.WriteFile(cfg, []byte(c), 0o644)
				cmd := exec.Command("/workspace/executable", "./...")
				cmd.Dir = dir
				out, _ := cmd.CombinedOutput()
				s := strings.ReplaceAll(string(out), "declscope: "+cfg+": ", "")
				s = strings.TrimRight(s, "\n")
				mu.Lock()
				cache[c] = s
				mu.Unlock()
			}
		}()
	}
	for _, c := range todo {
		ch <- c
	}
	close(ch)
	wg.Wait()
	b, _ := json.Marshal(cache)
	os.WriteFile(cacheFile, b, 0o644)
	fmt.Fprintf(os.Stderr, "ran %d new cases, cache has %d\n", len(todo), len(cache))
}
EOF
