		if len(n.Content) == 2 && n.Content[0].Kind == yaml.ScalarNode && n.Content[0].Value == "rules" && n.Content[0].Style == 0 {
			r := n.Content[1]
			if r.Kind == yaml.MappingNode && len(r.Content) == 2 && r.Content[0].Value == "boundary" && r.Content[0].Kind == yaml.ScalarNode {
				v := r.Content[1]
				if v.Kind != yaml.ScalarNode || v.Style&yaml.TaggedStyle != 0 && v.Tag != "!!str" {
					return "", false
				}
				if v.ShortTag() == "!!null" || v.Value == "" || v.Value == "off" || v.Value == "on" {
					return "", true
				}
				return fmt.Sprintf("rules.boundary: unknown mode %q (want off or on)", v.Value), true
			}
			return "", false
		}
		var lines []string
		seen := map[string]bool{}
		for i := 0; i < len(n.Content); i += 2 {
			k := n.Content[i]
			if k.Kind != yaml.ScalarNode || k.Style&yaml.TaggedStyle != 0 || k.ShortTag() == "!!null" || seen[k.Value] || known[k.Value] {
				return "", false
			}
			seen[k.Value] = true
			lines = append(lines, fmt.Sprintf("line %d: unknown key %q (this section takes defaults, rules, filter, baseline)", k.Line, k.Value))
		}
		return strings.Join(lines, "\n"), true
	}
	return "", false
}

func isDecodeError(s string) bool {
	for _, p := range []string{"yaml: cannot decode", "yaml: !!binary", "yaml: anchor ", "yaml: document contains excessive aliasing"} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

func main() {
	verbose := flag.Bool("v", false, "print matching cases too")
	flag.Parse()
	cache := map[string]string{}
	b, err := os.ReadFile("/tmp/ycmp/cache.json")
	if err != nil {
		panic(err)
	}
	json.Unmarshal(b, &cache)
	var pass, fail, missing, unchecked int
	for _, c := range readCorpus(flag.Args()) {
		want, ok := cache[c]
		if !ok {
			missing++
			continue
		}
		doc, perr := yaml.Parse([]byte(c))
		var got string
		checked := true
		if perr != nil {
			got = perr.Error()
		} else {
			got, checked = emulate(doc)
		}
		wantIsSyntax := strings.HasPrefix(want, "yaml: ") && !isDecodeError(want)
		good := false
		switch {
		case wantIsSyntax || perr != nil:
			good = got == want
		case !checked:
			good = true
			unchecked++
		default:
			good = got == want
		}
		if good {
			pass++
			if *verbose {
				fmt.Printf("ok   %q\n     %q\n", c, want)
			}
		} else {
			fail++
			fmt.Printf("FAIL %q\n  want %q\n  got  %q\n", c, want, got)
		}
	}
	fmt.Printf("pass %d (unchecked shape %d) fail %d missing %d\n", pass, unchecked, fail, missing)
}
