	"strconv"
	"strings"
)

func readCorpus(f string) []string {
	var cases []string
	fh, _ := os.Open(f)
	sc := bufio.NewScanner(fh)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		s, _ := strconv.Unquote(line)
		cases = append(cases, s)
	}
	return cases
}

var (
	modeRe = regexp.MustCompile(`^rules\.boundary: unknown mode (".*") \(want off or on\)$`)
	tagRe  = regexp.MustCompile("^line (\\d+): cannot unmarshal (\\S+) `(.*)` into config\\.File$")
)

func main() {
	mode, maxLen := os.Args[1], 200
	cache := map[string]string{}
	b, _ := os.ReadFile("/tmp/ycmp/cache2.json")
	json.Unmarshal(b, &cache)
	seen := map[string]bool{}
	for _, f := range os.Args[2:] {
		for _, c := range readCorpus(f) {
			if seen[c] || len(c) > maxLen {
				continue
			}
			seen[c] = true
			w64, ok := cache[base64.StdEncoding.EncodeToString([]byte(c))]
			if !ok {
				continue
			}
			wb, _ := base64.StdEncoding.DecodeString(w64)
			want := string(wb)
			isSyntax := strings.HasPrefix(want, "yaml: ") && !strings.HasPrefix(want, "yaml: cannot decode") &&
				!strings.HasPrefix(want, "yaml: !!binary") && !strings.HasPrefix(want, "yaml: map merge")
			switch mode {
			case "errors":
				if isSyntax {
					fmt.Printf("\t\t{%q, %q},\n", c, want)
				}
			case "valid":
				if !strings.HasPrefix(want, "yaml: ") {
					fmt.Printf("\t\t%q,\n", c)
				}
			case "values":
				if m := modeRe.FindStringSubmatch(want); m != nil && strings.HasPrefix(c, "rules:\n  boundary:") {
					v, err := strconv.Unquote(m[1])
					if err == nil {
						fmt.Printf("\t\t{%q, %q},\n", c, v)
					}
				}
			case "tags":
				if m := tagRe.FindStringSubmatch(want); m != nil && !strings.Contains(m[3], "...") {
					fmt.Printf("\t\t{%q, %q, %s, %q},\n", c, m[2], m[1], m[3])
				}
			}
		}
	}
}
EOF
cd /tmp/ycmp && go build -o bin/gentest ./cmd/gentest && for m in errors valid values tags; do ./bin/gentest $m corpus/c1.txt > /tmp/ycmp/tbl_$m.txt; wc -l /tmp/ycmp/tbl_$m.txt; done; head -5 /tmp/ycmp/tbl_tags.txt

