// Command fromfuzz converts a Go fuzz corpus directory into a corpus file.
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func main() {
	entries, _ := os.ReadDir(os.Args[1])
	var b strings.Builder
	n := 0
	for _, e := range entries {
		data, _ := os.ReadFile(filepath.Join(os.Args[1], e.Name()))
		for _, line := range strings.Split(string(data), "\n")[1:] {
