1	package yaml
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	// Parse parses the first document of data into a node tree, as
9	// yaml.Unmarshal(data, &node) does with gopkg.in/yaml.v3. It returns the
10	// document node, or nil if data holds no document (it is empty or holds only
11	// comments). On malformed input it returns the error yaml.v3 returns, such
12	// as "yaml: line 2: found character that cannot start any token".
13	//
14	// Anything after the first document is ignored, except that the scanner
15	// reads a few tokens ahead and reports an error it finds there.
16	func Parse(data []byte) (doc *Node, err error) {
17		defer handleErr(&err)
18		if len(data) == 0 {
19			data = []byte{'\n'}
20		}
21		c := &composer{p: newParser(data), anchors: make(map[string]*Node)}
22		c.expect(streamStartEvent)
23		return c.parse(), nil
24	}
25	
26	// syntaxError carries a parse error up to Parse.
27	type syntaxError struct{ err error }
28	
29	func failf(format string, args ...any) {
30		panic(syntaxError{fmt.Errorf("yaml: "+format, args...)})
31	}
32	
33	func handleErr(err *error) {
34		if v := recover(); v != nil {
35			e, ok := v.(syntaxError)
36			if !ok {
37				panic(v)
38			}
39			*err = e.err
40		}
41	}
42	
43	// composer builds nodes from parser events, following yaml.v3.
44	type composer struct {
45		p       *parser
46		event   event // The event peeked at but not consumed yet, if any.
47		anchors map[string]*Node
48	}
49	
50	func (c *composer) fail() {
51		panic(syntaxError{errors.New(c.p.errorMessage())})
52	}
53	
54	// peek returns the type of the next event without consuming it.
55	func (c *composer) peek() eventType {
56		if c.event.typ != noEvent {
57			return c.event.typ
58		}
59		if !c.p.parse(&c.event) || c.p.err != noError {
60			c.fail()
61		}
62		return c.event.typ
63	}
64	
65	// expect consumes the next event, which must be of type t.
66	func (c *composer) expect(t eventType) {
67		if c.event.typ == noEvent && !c.p.parse(&c.event) {
68			c.fail()
69		}
70		if c.event.typ == streamEndEvent {
71			failf("attempted to go past the end of stream; corrupted value?")
72		}
73		if c.event.typ != t {
74			c.p.problem = fmt.Sprintf("expected %s event but got %s", t, c.event.typ)
75			c.fail()
76		}
77		c.event = event{}
78	}
79	
80	func (c *composer) parse() *Node {
81		switch c.peek() {
82		case scalarEvent:
83			return c.scalar()
84		case aliasEvent:
85			return c.alias()
86		case mappingStartEvent:
87			return c.mapping()
88		case sequenceStartEvent:
89			return c.sequence()
90		case documentStartEvent:
91			return c.document()
92		case streamEndEvent:
93			return nil
94		}
95		panic("yaml: internal error: unexpected " + c.event.typ.String() + " event")
96	}
97	
98	// node creates a node for the current event. An explicit tag other than
99	// the non-specific "!" wins; otherwise collections and quoted scalars get
100	// defaultTag and plain scalars a tag resolved from their value.
101	func (c *composer) node(kind Kind, defaultTag, tag, value string) *Node {
102		var style Style
103		switch {
104		case tag != "" && tag != "!":
105			tag = shortTag(tag)
106			style = TaggedStyle
107		case defaultTag != "":
108			tag = defaultTag
109		case kind == ScalarNode:
110			tag = resolveTag(value)
111		}
112		return &Node{
113			Kind:   kind,
114			Style:  style,
115			Tag:    tag,
116			Value:  value,
117			Line:   c.event.start.line + 1,
118			Column: c.event.start.column + 1,
119		}
120	}
121	
122	func (c *composer) anchor(n *Node, anchor []byte) {
123		if anchor != nil {
124			n.Anchor = string(anchor)
125			c.anchors[n.Anchor] = n
126		}
127	}
128	
129	func (c *composer) document() *Node {
130		n := c.node(DocumentNode, "", "", "")
131		c.expect(documentStartEvent)
132		n.Content = append(n.Content, c.parse())
133		c.peek()
134		c.expect(documentEndEvent)
135		return n
136	}
137	
138	func (c *composer) alias() *Node {
139		n := c.node(AliasNode, "", "", string(c.event.anchor))
140		n.Alias = c.anchors[n.Value]
141		if n.Alias == nil {
142			failf("unknown anchor '%s' referenced", n.Value)
143		}
144		c.expect(aliasEvent)
145		return n
146	}
147	
148	func (c *composer) scalar() *Node {
149		var style Style
150		switch c.event.style {
151		case doubleQuotedScalarStyle:
152			style = DoubleQuotedStyle
153		case singleQuotedScalarStyle:
154			style = SingleQuotedStyle
155		case literalScalarStyle:
156			style = LiteralStyle
157		case foldedScalarStyle:
158			style = FoldedStyle
159		}
160		value := string(c.event.value)
161		var defaultTag string
162		if style != 0 {
163			defaultTag = strTag
164		} else if value == "<<" {
165			defaultTag = mergeTag
166		}
167		n := c.node(ScalarNode, defaultTag, string(c.event.tag), value)
168		n.Style |= style
169		c.anchor(n, c.event.anchor)
170		c.expect(scalarEvent)
171		return n
172	}
173	
174	func (c *composer) sequence() *Node {
175		n := c.node(SequenceNode, seqTag, string(c.event.tag), "")
176		if c.event.flow {
177			n.Style |= FlowStyle
178		}
179		c.anchor(n, c.event.anchor)
180		c.expect(sequenceStartEvent)
181		for c.peek() != sequenceEndEvent {
182			n.Content = append(n.Content, c.parse())
183		}
184		c.expect(sequenceEndEvent)
185		return n
186	}
187	
188	func (c *composer) mapping() *Node {
189		n := c.node(MappingNode, mapTag, string(c.event.tag), "")
190		if c.event.flow {
191			n.Style |= FlowStyle
192		}
193		c.anchor(n, c.event.anchor)
194		c.expect(mappingStartEvent)
195		for c.peek() != mappingEndEvent {
196			k := c.parse()
197			v := c.parse()
198			n.Content = append(n.Content, k, v)
199		}
200		c.expect(mappingEndEvent)
201		return n
202	}
