72						if len(text) > 0 {
73							if startMark.column-1 < nextIndent {
74								// Dedented, it is unrelated to the prior token.
75								tokenMark = startMark
76							}
77							addFoot(mark{p.mark.index + peek, line, column})
78						}
79					} else if len(text) > 0 && p.at(peek) != 0 {
80						text = append(text, '\n')
81					}
82				}
83				if !p.isBreak(peek) {
84					break
85				}
86				firstEmpty = false
87				recentEmpty = true
88				column = 0
89				line++
90				continue
91			}
92	
93			if len(text) > 0 && column-1 < nextIndent && column != startMark.column {
94				// A comment at a different indentation is a foot of the
95				// preceding content rather than a head of what follows.
96				addFoot(mark{p.mark.index + peek, line, column})
97			}
98	
99			if c != '#' {
100				break
101			}
102			if len(text) == 0 {
103				startMark = mark{p.mark.index + peek, line, column}
104			} else {
105				text = append(text, '\n')
106			}
107			recentEmpty = false
108	
109			// Consume up to the end of this comment line.
110			seen := p.mark.index + peek
111			for {
112				if p.unread < 1 && !p.updateBuffer(1) {
113					return false
114				}
