import random, sys
sys.path.insert(0, '/tmp/ycmp/gen')
from qlib import q
seed = int(sys.argv[1]); n = int(sys.argv[2]); outp = sys.argv[3]
random.seed(seed)

def scalar(ind):
    r = random.random()
    if r < 0.25: return random.choice(["a", "b c", "1", "-x", "x:y", "x#y", "~", "''", "\"\"", "'q r'", "\"e\\tf\"", "&a v", "*a", "!t v", "!!str 1"])
    if r < 0.4: return "|" + random.choice(["", "-", "+", "2"]) + "\n" + " " * (ind + 2) + "l1\n" + " " * (ind + 2) + "l2"
    if r < 0.5: return "plain\n" + " " * (ind + random.choice([1, 2, 0])) + "cont"
    if r < 0.6: return "'sq\n" + " " * random.choice([0, 1, ind + 2]) + "more'"
    if r < 0.7: return "\"dq\n" + " " * random.choice([0, 1, ind + 2]) + "more\""
    if r < 0.85: return flow(ind)
    return random.choice(["", " # c", "&x", "!t", "&x !t"])

def flow(ind):
    items = []
    for _ in range(random.randint(0, 3)):
        r = random.random()
        if r < 0.5: items.append(random.choice(["a", "1", "'q'", "\"d\"", "*a", "&b c", "x: y", "? z", ": w", ""]))
        elif r < 0.7: items.append(flow(ind))
        else: items.append(random.choice(["\n" + " " * random.choice([0, 1, ind, ind + 2]) + "nl", "# c\n" + " " * (ind + 1) + "k"]))
    sep = random.choice([", ", ",", ",\n" + " " * random.choice([0, ind, ind + 1])])
    if random.random() < 0.5:
        return "[" + sep.join(items) + random.choice(["]", "]", "", ",]"])
    return "{" + sep.join(items) + random.choice(["}", "}", "", ",}"])

def block(depth, ind):
    out = []
    kind = random.choice(["map", "seq", "map", "explicit"])
    for _ in range(random.randint(1, 3)):
        pad = " " * ind
        nested = depth < 3 and random.random() < 0.5
        props = random.choice(["", "", "", " &a", " !t", " &a !t", " !!map", " !!seq"]) if nested else ""
        if kind == "map":
            k = random.choice(["k", "key", "'k q'", "\"k\"", "[a]", "{a: b}", "&k k", "*a", "1", "k k"])
            if nested:
                out.append(pad + k + ":" + props + random.choice(["", " # c"]))
                out.extend(block(depth + 1, ind + random.choice([0, 1, 2, 4])))
            else:
                out.append(pad + k + ": " + scalar(ind))
        elif kind == "seq":
            if nested:
                if random.random() < 0.5:
                    out.append(pad + "-" + props)
                    out.extend(block(depth + 1, ind + random.choice([1, 2, 4])))
                else:
                    sub = block(depth + 1, ind + 2)
                    out.append(pad + "- " + sub[0].lstrip(" "))
                    out.extend(sub[1:])
            else:
                out.append(pad + "- " + scalar(ind))
        else:
            out.append(pad + "? " + scalar(ind))
            if random.random() < 0.8:
                if nested:
                    out.append(pad + ":" + props)
                    out.extend(block(depth + 1, ind + 2))
                else:
                    out.append(pad + ": " + scalar(ind))
    return out

def perturb(lines):
    for _ in range(random.randint(0, 2)):
        if not lines: break
        i = random.randrange(len(lines))
        r = random.random()
        if r < 0.3: lines[i] = " " + lines[i]
        elif r < 0.5 and lines[i].startswith(" "): lines[i] = lines[i][1:]
        elif r < 0.6: lines[i] = lines[i].replace(" ", "\t", 1)
        elif r < 0.75:
            j = random.randrange(len(lines[i]) + 1)
            lines[i] = lines[i][:j] + random.choice([":", "-", "?", "#", "'", "\"", "[", "]", "{", "}", ",", "&", "*", "!", "|", ">", "@", "%"]) + lines[i][j:]
        elif r < 0.85: lines.insert(i, random.choice(["", "# c", "  # c", "---", "...", "%YAML 1.1"]))
    return lines

cases = set()
while len(cases) < n:
    lines = block(0, random.choice([0, 0, 1, 2]))
    if random.random() < 0.7:
        lines = perturb(lines)
    pre = random.choice(["", "", "---\n", "--- ", "%YAML 1.1\n---\n", "# head\n", "\n"])
    s = pre + "\n".join(lines) + random.choice(["\n", "", "\n...\n", "\n---\nz: @\n"])
    cases.add(s)
with open(outp, 'w') as f:
    for c in sorted(cases):
        f.write(q(c) + "\n")
