cd /tmp/ycmp && python3 gen/gen10.py 10 10000 corpus/g1.txt && time ./bin/runbin corpus/g1.txt && ./bin/cmp corpus/g1.txt > g1.out; tail -1 g1.out; grep -A2 FAIL g1.out | cut -c1-300 | head -40

