// emulateSection appends the unknown-key messages for mapping m of the
// named section, in document order. It reports false for shapes it does not
// cover.
func emulateSection(m *yaml.Node, name string, lines *[]string) bool {
	if m.Kind != yaml.MappingNode || m.Tag != "!!map" {
		return false
	}
	sec := sections[name]
	seen := map[string]bool{}
	for i := 0; i+1 < len(m.Content); i += 2 {
		k, v := m.Content[i], m.Content[i+1]
		if k.Kind != yaml.ScalarNode || k.Style&yaml.TaggedStyle != 0 || k.ShortTag() == "!!null" || seen[k.Value] || !simpleKey(k.Value) || k.Anchor != "" {
			return false
		}
		seen[k.Value] = true
		if sec.leaves[k.Value] {
			return false
		}
		if child, ok := sec.containers[k.Value]; ok {
			if v.Kind == yaml.ScalarNode && v.ShortTag() == "!!null" && v.Style&yaml.TaggedStyle == 0 && v.Anchor == "" {
				continue
			}
			if v.Anchor != "" || !emulateSection(v, child, lines) {
				return false
			}
			continue
		}
		path := k.Value
		if name != "" {
			path = name + "." + k.Value
		}
		*lines = append(*lines, fmt.Sprintf("line %d: unknown key %q (this section takes %s)", k.Line, path, sec.takes))
	}
	return true
}

