	data, err := os.ReadFile(name)
	if err != nil {
		return nil, err
	}
	fs := &FileSection{Path: abs, Dir: filepath.Dir(abs)}
	doc, err := yaml.Parse(data)
	if err != nil {
		return nil, fmt.Errorf("%s: %v", abs, err)
	}
	if err := decodeConfig(doc, fs); err != nil {
		return nil, fmt.Errorf("%s: %v", abs, err)
