				From:        ns.key(),
				To:          d.ns.key(),
				Declaration: d.display,
				Kind:        d.kind,
				Uses:        uses[ns],
				State:       st,
				decl:        d,
			})
		}
	}
	sort.SliceStable(me.Edges, func(i, j int) bool {
		a, b := me.Edges[i], me.Edges[j]
		if a.From != b.From {
			return a.From < b.From
		}
		if a.To != b.To {
			return a.To < b.To
		}
		return a.Declaration < b.Declaration
	})
