	cells = nil
	for _, p := range rows {
		largest := "-"
		if p.Largest != nil {
			largest = fmt.Sprintf("%s → %s (%s)", p.Largest.From, p.Largest.To, plural(p.Largest.Reached, "declaration", "declarations"))
