			t.Reported += c.Reported
		}
		rows = append(rows, surveyRow(me))
	}
	sort.SliceStable(rows, func(i, j int) bool {
		a := rows[i].Boundary.Reported + rows[i].Boundary.Baselined
		b := rows[j].Boundary.Reported + rows[j].Boundary.Baselined
		if a != b {
			return a > b
		}
		return rows[i].Package < rows[j].Package
	})
	if sc.format == "json" {
		type checks struct {
