arguments.command:
python3 - <<'EOF'
p='/workspace/internal/analyzer/shrink_uses.go'
s=open(p).read()
s=s.replace('''const (
	reasonXTest    = "external tests use it"''','''const (
	reasonOwnExcl  = "a build-excluded file of its package names it"
	reasonXTest    = "external tests use it"''')
s=s.replace('''	mayUse   map[token.Pos]bool
}''','''	mayUse   map[token.Pos]bool
	ownNames map[*shrinkUnit]map[string]bool
}''')
s=s.replace('''		mayUse:  make(map[token.Pos]bool),
	}''','''		mayUse:   make(map[token.Pos]bool),
		ownNames: make(map[*shrinkUnit]map[string]bool),
	}''')
old='''	for _, u := range us {
		st.scanExcluded(u)
	}'''
new='''	st.scanExcluded(us)'''
assert old in s
s=s.replace(old,new)
start=s.index('// scanExcluded reads the build-excluded files')
end=s.index('// constSets treats a block')
s=s[:start]+'''// scanExcluded reads the Go files of the module that no package loaded,
// for the names they write, since they are not type-checked.
func (st *shrinkState) scanExcluded(us []*unit) {
	loaded := make(map[string]bool)
	var roots []string
	for _, u := range us {
		p := u.pkg
		for _, f := range p.GoFiles {
			loaded[f] = true
		}
		for _, f := range p.CompiledGoFiles {
			loaded[f] = true
		}
		if p.Raw != nil {
			for _, list := range [][]string{p.TestGoFiles(), p.XTestGoFiles()} {
				for _, f := range list {
					loaded[f] = true
				}
			}
		}
		if p.Module != nil && p.Module.Dir != "" {
			roots = append(roots, p.Module.Dir)
		}
	}
	sort.Strings(roots)
	byDir := make(map[string]*shrinkUnit)
	for _, su := range st.res.units {
		byDir[su.pkg.Dir] = su
	}
	seenRoot := make(map[string]bool)
	for _, root := range roots {
		if seenRoot[root] {
			continue
		}
		seenRoot[root] = true
		for _, path := range moduleGoFiles(root) {
			if loaded[path] {
				continue
			}
			st.readExcluded(path, byDir)
		}
	}
}

// moduleGoFiles lists the Go files under a module root the way ./... walks
// it: no testdata, vendor, hidden or underscore directories, and no nested
// modules.
func moduleGoFiles(root string) []string {
	var out []string
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		name := d.Name()
		if d.IsDir() {
			if path == root {
				return nil
			}
			if strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") || name == "testdata" || name == "vendor" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir
			}
			return nil
