new='''// domain lists the declarations a directive is written over, whether or
// not they take their scope from it.
func (m *model) domain(dir *directive) []*decl {
	var out []*decl
	for _, d := range m.decls {
		if dir.fileLevel {
			if d.file == dir.file {
				out = append(out, d)
			}
			continue
		}
		for t := d.target; t != nil; t = t.parent {
			if t == dir.target {
				out = append(out, d)
				break
			}
		}
	}
	return out
}

// unusedScopeFindings reports scope directives that change nothing.
func (m *model) unusedScopeFindings(fixes bool, base []*finding) []*finding {
	if m.rules.Unused == "off" {
		return nil
	}
	strict := m.rules.Unused == "strict"
	var out []*finding
	all := m.scopeDirectives()
	for _, dir := range all {
		prefix := "unused //declscope:" + dir.name
		if dir.fileLevel {
			prefix = "unused file-level //declscope:" + dir.name
		}
		report := func(msg string, fixable bool) {
			f := &finding{rule: "unused", pos: dir.pos(), message: msg, dir: dir, unusedOf: true}
			if fixable && strict && fixes && !(m.unseenTests && !m.testVariant) && !m.changesFindings(dir, base) {
				f.fix = &checker.SuggestedFix{
					Message:   "remove //declscope:" + dir.name,
					TextEdits: []checker.TextEdit{m.deleteDirective(dir)},
				}
			}
			out = append(out, f)
		}
		domain := m.domain(dir)
		reach := m.reached(dir)
		if len(domain) == 0 {
			if dir.fileLevel {
				report(prefix, false)
			} else {
				report(prefix+": no checked declaration carries it", false)
			}
			continue
		}
		if len(reach) == 0 {
			switch {
			case !dir.fileLevel:
				report(prefix+": every declaration it reaches states its own scope", true)
			case strict:
				report(prefix+": every declaration it reaches takes a nearer directive's scope", true)
			default:
				report(prefix, false)
			}
			continue
		}
		skip := map[*directive]bool{dir: true}
		same, configFree := true, true
		for _, d := range reach {
			s, src := m.scopeOf(d, skip)
			if s != dir.name {
				same = false
			}
			if src.kind == srcDefault {
				configFree = false
			}
		}
		if !same {
			continue
		}
		names := m.dirNames(dir, reach)
		looseMsg := prefix
		if !dir.fileLevel {
			looseMsg = fmt.Sprintf("%s on %s: nothing it reaches takes a scope", prefix, strings.Join(names, ", "))
		}
		if !strict {
			if configFree {
				report(looseMsg, false)
			}
			continue
		}
		// Deleting it must not make a nearer directive redundant; when it
		// would, only a directive no configuration could need is reported.
		keeps := false
		for _, other := range all {
			if other == dir {
				continue
			}
			if !m.redundant(other, nil) && m.redundant(other, skip) {
				keeps = true
				break
			}
		}
		if keeps {
			if configFree {
				report(looseMsg, false)
			}
			continue
		}
		var msg string
		if dir.fileLevel {
			nearer, already := false, false
			for _, d := range domain {
				if d.source.dir != dir && d.scope != dir.name {
					nearer = true
				} else {
					already = true
				}
			}
			switch {
			case nearer && already:
				msg = fmt.Sprintf("%s: every declaration it reaches takes a nearer directive's scope or already has %s scope", prefix, dir.name)
			case nearer:
				msg = prefix + ": every declaration it reaches takes a nearer directive's scope"
			default:
				msg = fmt.Sprintf("%s: every declaration it reaches already has %s scope", prefix, dir.name)
			}
		} else {
			each := "it already has"
			if len(names) > 1 {
				each = "each already has"
			}
			msg = fmt.Sprintf("%s on %s: %s %s scope", prefix, strings.Join(names, ", "), each, dir.name)
		}
		report(msg, true)
	}
	return out
}

