func sortEdits(edits []TextEdit) {
	slices.SortStableFunc(edits, func(x, y TextEdit) int {
		if sign := cmp.Compare(x.Pos, y.Pos); sign != 0 {
			return sign
		}
		return cmp.Compare(x.End, y.End)
	})
}

