	}
	var out []*finding
	all := m.scopeDirectives()
	for _, dir := range all {
		r := m.unusedOf(dir, nil, all)
		if r.message == "" {
			continue
		}
		f := &finding{rule: "unused", pos: dir.pos(), message: r.message, dir: dir, unusedOf: true}
		if r.strict && fixes && !(m.unseenTests && !m.testVariant) && !m.changesFindings(dir, base) && !m.changesUnused(dir, all) {
			f.fix = &checker.SuggestedFix{
