		}
		out = append(out, f)
	}
	return out
}

// changesUnused reports whether deleting dir would change what the unused
// rule says of another directive.
func (m *model) changesUnused(dir *directive, all []*directive) bool {
	mine := make(map[*decl]bool)
	for _, d := range m.domain(dir) {
		mine[d] = true
	}
	without := map[*directive]bool{dir: true}
	for _, y := range all {
		if y == dir {
			continue
		}
		overlaps := false
		for _, d := range m.domain(y) {
			if mine[d] {
				overlaps = true
				break
			}
		}
		if overlaps && m.unusedOf(y, nil, all).message != m.unusedOf(y, without, all).message {
			return true
		}
	}
	return false
}

