python3 - <<'EOF'
p='/workspace/internal/analyzer/analyzer.go'
s=open(p).read()
old_start=s.index('func (m *model) filterFinding() *finding {')
old_end=s.index('\n}\n', old_start)+3
new='''func (m *model) filterFinding() *finding {
	only := m.rules.Only
	if len(only) == 0 {
		return nil
	}
	var paths []string
	var first *ast.File
	for _, f := range m.pass.Files {
		if ast.IsGenerated(f) {
			continue
		}
		if first == nil {
			first = f
		}
		paths = append(paths, m.fset.File(f.Pos()).Name())
	}
	// The nearest only matched files, and the rest of the filter took
	// every one of them back out.
	nearest := only[len(only)-1]
	matched := 0
	for _, p := range paths {
		if m.rules.admits(p) {
			return nil
		}
		if matchesList(nearest, p) {
			matched++
		}
	}
	if matched == 0 {
		return nil
	}
	return &finding{
		rule:    "filter",
		pos:     first.FileStart,
		message: fmt.Sprintf("filter.only stated in %s matches %d file(s) here, but an only above it removes them all, so this package is read as empty", nearest.Dir, matched),
	}
}
'''
s=s[:old_start]+new+s[old_end:]
open(p,'w').write(s)
