func (m *model) changesFindings(dir *directive, base []*finding) bool {
	m.resolveScopes(map[*directive]bool{dir: true})
	defer m.resolveScopes(nil)
	others := func(fs []*finding) []*finding {
		var out []*finding
		for _, f := range fs {
			if f.dir != dir {
				out = append(out, f)
			}
		}
		return out
	}
	after := others(m.declFindings(true))
	before := others(base)
	if len(after) != len(before) {
		return true
	}
	// The fix of a silenced finding is never offered.
	fixOf := func(f *finding) string {
		if f.fix == nil || len(m.covering(f)) > 0 {
			return ""
		}
		return f.fix.Message
	}
	for i := range after {
		a, b := after[i], before[i]
		if a.rule != b.rule || a.pos != b.pos || a.message != b.message || fixOf(a) != fixOf(b) {
			return true
		}
	}
	return false
}
func (m *model) changesUnused(dir *directive, all []*directive) bool {
	mine := make(map[*decl]bool)
	for _, d := range m.domain(dir) {
		mine[d] = true
	}
	without := map[*directive]bool{dir: true}
	for _, y := range all {
		if y == dir {
			continue
		}
		overlaps := false
		for _, d := range m.domain(y) {
			if mine[d] {
				overlaps = true
				break
			}
		}
		if overlaps && m.unusedOf(y, nil, all) != m.unusedOf(y, without, all) {
			return true
		}
	}
	return false
}

