#!/usr/bin/env python3
"""Random multi-package module generator for shrink/survey/baseline: txtar to stdout."""
import random
import sys

seed = int(sys.argv[1])
R = random.Random(seed)

NAMES = ["Load", "Store", "Parse", "Format", "Item", "Cache", "Order", "User", "ID", "Config",
         "Handler", "Server", "Client", "Value", "Record", "Status", "Key", "Name", "Kind", "Mode"]


class Pkg:
    def __init__(self, path, name):
        self.path = path
        self.name = name
        self.files = {}
        self.exported = []  # (kind, name, extra)


def nm(used):
    while True:
        n = R.choice(NAMES) + R.choice(["", "s", "er", "2", "Info", "Set"])
        if n not in used:
            used.add(n)
            return n


def gen_internal(path, name, used):
    p = Pkg(path, name)
    files = R.sample(["a.go", "b.go", "types.go", "util.go", "a_test.go", "x_test.go"], R.randint(1, 4))
    if not any(not f.endswith("_test.go") for f in files):
        files.append("main.go" if R.random() < 0.05 else "core.go")
    for f in files:
        body = []
        if f == "x_test.go":
            continue
        test = f.endswith("_test.go")
        for _ in range(R.randint(1, 5)):
            kind = R.choice(["func", "var", "const", "struct", "iface", "method", "consts", "generic", "strvar", "embed"])
            n = nm(used)
            if kind == "func":
                ret = R.choice(["", " int", " error", " *" + "T"])
                if ret == " *T":
                    ret = ""
                body.append("func %s()%s {%s}" % (n, ret, " return 0 " if ret == " int" else (" return nil " if ret == " error" else "")))
                p.exported.append(("func", n, None, test))
            elif kind == "var":
                body.append("var %s = %d" % (n, R.randint(1, 9)))
                p.exported.append(("var", n, None, test))
            elif kind == "strvar":
                body.append('var %s = "x"' % n)
                p.exported.append(("var", n, None, test))
            elif kind == "const":
                body.append("const %s = %d" % (n, R.randint(1, 9)))
                p.exported.append(("const", n, None, test))
            elif kind == "consts":
                t = nm(used)
                a, b = nm(used), nm(used)
                body.append("type %s int\n\nconst (\n\t%s %s = iota\n\t%s\n)" % (t, a, t, b))
                p.exported.append(("type", t, None, test))
                p.exported.append(("const", a, None, test))
                p.exported.append(("const", b, None, test))
            elif kind == "struct":
                fields = [nm(used) for _ in range(R.randint(1, 3))]
                tags = ["", "", "", ' `json:"x"`']
                body.append("type %s struct {\n%s\n}" % (n, "\n".join("\t%s int%s" % (x, R.choice(tags)) for x in fields)))
                p.exported.append(("struct", n, fields, test))
            elif kind == "embed":
                structs = [e for e in p.exported if e[0] == "struct"]
                if not structs:
                    continue
                e = R.choice(structs)
                body.append("type %s struct {\n\t%s\n\tX%s int\n}" % (n, e[1], n))
                p.exported.append(("struct", n, [e[1], "X" + n], test))
            elif kind == "iface":
                ms = [nm(used) for _ in range(R.randint(1, 2))]
                body.append("type %s interface {\n%s\n}" % (n, "\n".join("\t%s()" % m for m in ms)))
                p.exported.append(("iface", n, ms, test))
            elif kind == "method":
                structs = [e for e in p.exported if e[0] == "struct" and e[3] == test]
                if not structs:
                    continue
                e = R.choice(structs)
                ptr = R.choice(["", "*"])
                body.append("func (%s%s) %s() {}" % (ptr, e[1], n))
                p.exported.append(("method", n, e[1], test))
            elif kind == "generic":
                body.append("type %s[T any] struct {\n\tV T\n}" % n)
                p.exported.append(("generic", n, None, test))
        # internal uses
        uses = []
        for e in R.sample(p.exported, min(len(p.exported), R.randint(0, 3))):
            if e[3] and not test:
                continue
            uses.append(use_expr(e, ""))
        if uses:
            body.append("func use%s() {\n%s\n}" % (f[:-3].replace("_", "").capitalize(), "\n".join("\t" + u for u in uses if u)))
        p.files[f] = "package %s\n\n%s\n" % (name, "\n\n".join(body))
    if "x_test.go" in files:
        cands = [e for e in p.exported if not e[3]]
        if cands:
            e = R.choice(cands)
            p.files["x_test.go"] = "package %s_test\n\nimport \"example.com/app/%s\"\n\nfunc useX() {\n\t%s\n}\n" % (name, path, use_expr(e, name + "."))
    return p


def use_expr(e, q):
    kind, n, extra, _ = e
    if kind == "func":
        return "_ = %s%s" % (q, n) if R.random() < 0.3 else "%s%s()" % (q, n)
    if kind in ("var", "const"):
        return "_ = %s%s" % (q, n)
    if kind == "type":
        return "var _ %s%s" % (q, n)
    if kind == "generic":
        return "_ = %s%s[int]{}" % (q, n)
    if kind == "struct":
        c = R.random()
        if c < 0.3:
            return "_ = %s%s{}" % (q, n)
        if c < 0.6 and extra:
            return "_ = %s%s{}.%s" % (q, n, R.choice(extra))
        if c < 0.8:
            return "var _ %s%s" % (q, n)
        return "_ = fmt.Sprint(%s%s{})" % (q, n) if False else "var _ any = %s%s{}" % (q, n)
    if kind == "iface":
        return "var _ %s%s" % (q, n) if R.random() < 0.5 else "_ = (%s%s).%s" % (q, n, R.choice(extra))
    if kind == "method":
        return "_ = (*%s%s).%s" % (q, extra, n)
    return ""


def main():
    used = set()
    out = []
    pkgs = [gen_internal("internal/a", "a", used), gen_internal("internal/b", "b", used)]
    if R.random() < 0.3:
        pkgs.append(gen_internal("internal/c/d", "d", used))
    for p in pkgs:
        for f, src in p.files.items():
            out.append("-- %s/%s --\n%s" % (p.path, f, src))
    # an api package using some exported decls
    imports = []
    uses = []
    for p in pkgs:
        chosen = [e for e in p.exported if not e[3] and R.random() < 0.35]
        if chosen:
            imports.append('"example.com/app/%s"' % p.path)
            for e in chosen:
                uses.append(use_expr(e, p.name + "."))
    if R.random() < 0.3 and len(pkgs) > 1:
        # cross internal import
        a, b = pkgs[0], pkgs[1]
        chosen = [e for e in b.exported if not e[3]]
        if chosen:
            e = R.choice(chosen)
            out.append("-- internal/a/zz.go --\npackage a\n\nimport \"example.com/app/internal/b\"\n\nfunc useB() {\n\t%s\n}\n" % use_expr(e, "b."))
    out.append("-- api/api.go --\npackage api\n\nimport (\n%s\n)\n\nfunc Use() {\n%s\n}\n" % ("\n".join("\t" + i for i in imports), "\n".join("\t" + u for u in uses)))
    if not imports:
        out[-1] = "-- api/api.go --\npackage api\n\nfunc Use() {}\n"
    out.insert(0, "-- go.mod --\nmodule example.com/app\n\ngo 1.22\n")
    if R.random() < 0.3:
        out.insert(1, "-- .declscope.yaml --\nrules:\n  naming:\n    qualify: %s\n" % R.choice(["never", "ondemand", "always"]))
    print("\n".join(out))
    print("-- @cmd --")
    print("\n".join(["$X shrink; echo \"exit $?\"", "$X shrink -fix; echo \"exit $?\"; cat internal/*/*.go",
                     "$X shrink ./internal/a; echo \"exit $?\"",
                     "$X baseline ./... ; echo \"exit $?\"; cat .declscope-baseline.yaml",
                     "$X survey ./... ; echo \"exit $?\"",
                     "go vet ./... >/dev/null 2>&1; $X shrink -fix >/dev/null 2>&1; go build ./... && echo BUILD_OK"]))


main()

