#!/usr/bin/env python3
"""Random interface/method-heavy package generator for the analyzer: txtar to stdout."""
import random
import sys

seed = int(sys.argv[1])
R = random.Random(seed)

FILES = ["user.go", "order.go", "store.go", "api.go", "core.go", "user_test.go", "util.go"]
SCOPE = ["", "", "", "//declscope:shared", "//declscope:private", "//declscope:ignore surplus", "//declscope:ignore boundary"]


def main():
    files = R.sample(FILES, R.randint(2, 4))
    if all(f.endswith("_test.go") for f in files):
        files.append("main.go")
    bodies = {f: [] for f in files}
    ifaces = []   # (name, methods, file)
    types_ = []   # (name, file, ptr)
    n = [0]

    def nm(base, exp=False):
        n[0] += 1
        s = "%s%d" % (base, n[0])
        return s[0].upper() + s[1:] if exp else s

    for f in files:
        for _ in range(R.randint(1, 3)):
            k = R.random()
            if k < 0.35:
                name = nm("iface", R.random() < 0.3)
                ms = [nm("m", R.random() < 0.3) for _ in range(R.randint(1, 3))]
                lines = []
                if ifaces and R.random() < 0.3:
                    lines.append("\t" + R.choice(ifaces)[0])
                for m in ms:
                    d = R.choice(SCOPE)
                    if d:
                        lines.append("\t" + d)
                    lines.append("\t%s()" % m)
                bodies[f].append((R.choice(SCOPE), "type %s interface {\n%s\n}" % (name, "\n".join(lines))))
                ifaces.append((name, ms, f))
            elif k < 0.7:
                name = nm("impl", R.random() < 0.3)
                lines = []
                if types_ and R.random() < 0.3:
                    lines.append("\t" + R.choice(types_)[0])
                lines.append("\tx int")
                bodies[f].append((R.choice(SCOPE), "type %s struct {\n%s\n}" % (name, "\n".join(lines))))
                types_.append((name, f, R.random() < 0.5))
            else:
                if not types_:
                    continue
                t = R.choice(types_)
                if ifaces and R.random() < 0.7:
                    i = R.choice(ifaces)
                    for m in i[1]:
                        ff = R.choice(files)
                        if ff.endswith("_test.go") and not t[1].endswith("_test.go"):
                            ff = t[1]
                        bodies[ff].append((R.choice(SCOPE), "func (r %s%s) %s() {}" % ("*" if t[2] else "", t[0], m)))
                    # assertion of implementation somewhere
                    ff = R.choice(files)
                    if not (ff.endswith("_test.go") is False and (t[1].endswith("_test.go") or i[2].endswith("_test.go"))):
                        bodies[ff].append(("", "var _ %s = %s%s{}" % (i[0], "&" if t[2] else "", t[0])))
                else:
                    m = nm("meth", R.random() < 0.3)
                    bodies[t[1]].append((R.choice(SCOPE), "func (r %s%s) %s() {}" % ("*" if t[2] else "", t[0], m)))
    # uses: call interface methods from various files
    for f in files:
        uses = []
        for _ in range(R.randint(0, 4)):
            if ifaces and R.random() < 0.6:
                i = R.choice(ifaces)
                if i[2].endswith("_test.go") and not f.endswith("_test.go"):
                    continue
                uses.append("\tvar v%d %s\n\tif v%d != nil { v%d.%s() }" % (n[0], i[0], n[0], n[0], R.choice(i[1])))
                n[0] += 1
            elif types_:
                t = R.choice(types_)
                if t[1].endswith("_test.go") and not f.endswith("_test.go"):
                    continue
                uses.append("\t_ = %s%s{}" % ("&" if t[2] else "", t[0]))
        if uses:
            bodies[f].append(("", "func use%s() {\n%s\n}" % (f[:-3].replace("_", "").capitalize(), "\n".join(uses))))
    out = []
    if R.random() < 0.5:
        out.append("-- .declscope.yaml --\nrules:\n  naming:\n    qualify: %s\n  surplus: %s\n  unused: %s\n" % (
            R.choice(["never", "ondemand", "always"]), R.choice(["strict", "loose"]), R.choice(["strict", "loose"])))
    for f in files:
        lines = ["package p", ""]
        for d, decl in bodies[f]:
            if d:
                lines.append(d)
            lines.append(decl)
            lines.append("")
        out.append("-- p/%s --\n%s" % (f, "\n".join(lines)))
    print("\n".join(out))
    print("-- @cmd --")
    print("\n".join(["$X ./...", "$X -json ./...", "$X -fix ./... ; $X ./...", "$X inspect ./p",
                     "go build ./... && echo BUILD_OK"]))


main()

