func (m *model) surplusUsed(d *decl) bool {
	if len(d.crossing()) > 0 {
		return true
	}
	if d.kind != "method" {
		return false
	}
	if d.typeDecl != nil && d.typeDecl.exported {
		// A method of an exported type may serve an interface declscope
		// cannot see.
		return true
	}
	if fn, ok := d.obj.(*types.Func); ok && m.exportedMethods()[fn] {
		// So may one an exported type gets by embedding.
		return true
	}
	fn, ok := d.obj.(*types.Func)
	if !ok {
		return false
	}
	// A method an interface of the package also declares may be called
	// through it, wherever that is.
	for _, other := range m.ifaceMethods() {
		if other != fn && other.Name() == fn.Name() && types.Identical(other.Type(), fn.Type()) {
			return true
		}
	}
	return false
}

