python3 - <<'EOF'
p='/workspace/internal/analyzer/rules.go'
s=open(p).read()
old='''	fn, ok := d.obj.(*types.Func)
	if !ok {
		return false
	}
	// A method an interface of the package also declares may be called
	// through it, wherever that is.
	for _, other := range m.ifaceMethods() {
		if other != fn && other.Name() == fn.Name() && types.Identical(other.Type(), fn.Type()) {
			return true
		}
	}
	return false
}'''
new='''	fn, ok := d.obj.(*types.Func)
	if !ok {
		return false
	}
	// A method may be called through another interface of the package that
	// declares it too and that its type satisfies, wherever that is.
	var holder types.Type
	if d.typeDecl != nil {
		holder = d.typeDecl.obj.Type()
	} else if sig, ok := fn.Type().(*types.Signature); ok && sig.Recv() != nil {
		holder = sig.Recv().Type()
	}
	if holder == nil {
		return false
	}
	for _, it := range m.ifaceTypes() {
		declared := false
		for i := 0; i < it.NumExplicitMethods(); i++ {
			if it.ExplicitMethod(i) == fn {
				declared = true
			}
		}
		if declared {
			continue
		}
		match := false
		for i := 0; i < it.NumMethods(); i++ {
			if other := it.Method(i); other != fn && other.Name() == fn.Name() && types.Identical(other.Type(), fn.Type()) {
				match = true
				break
			}
		}
		if !match {
			continue
		}
		if types.Implements(holder, it) {
			return true
		}
		if !types.IsInterface(holder) {
			if _, isPtr := holder.(*types.Pointer); !isPtr && types.Implements(types.NewPointer(holder), it) {
				return true
			}
		}
	}
	return false
}

// ifaceTypes lists the interface types the analyzed files spell.
func (m *model) ifaceTypes() []*types.Interface {
	if m.ifaceTys != nil {
		return m.ifaceTys
	}
	m.ifaceTys = []*types.Interface{}
	for _, f := range m.files {
		ast.Inspect(f.ast, func(n ast.Node) bool {
			if it, ok := n.(*ast.InterfaceType); ok {
				if t, ok := m.pass.TypesInfo.Types[it].Type.(*types.Interface); ok {
					m.ifaceTys = append(m.ifaceTys, t)
				}
			}
			return true
		})
	}
	return m.ifaceTys
}'''
