$(cat)
-- @cmd --
\$X ./...; echo "exit \$?"
\$X survey -format=json ./... | grep -A6 '"surplus"' | head -7
\$X baseline -shrink=false ./...; \$X survey -format=json ./... | grep -A6 '"surplus"' | head -7; \$X ./...
EOF
}
mk ca <<'EOF'
-- p/user.go --
//declscope:shared

package p

//declscope:ignore surplus
